PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),institution_name TEXT,account_name TEXT,account_type TEXT,current_balance INTEGER NOT NULL,available_balance INTEGER NOT NULL,currency TEXT DEFAULT 'USD',is_active INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS transaction_categories(id TEXT PRIMARY KEY,name TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS merchant_aliases(alias TEXT PRIMARY KEY,normalized TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY,account_id TEXT NOT NULL REFERENCES accounts(id),external_id TEXT,posted_date TEXT NOT NULL,transaction_date TEXT NOT NULL,merchant_raw TEXT,merchant_normalized TEXT,description TEXT,amount INTEGER NOT NULL,currency TEXT DEFAULT 'USD',category TEXT,transaction_type TEXT,is_pending INTEGER DEFAULT 0,is_internal_transfer INTEGER DEFAULT 0,is_refund INTEGER DEFAULT 0,duplicate_group_id TEXT,is_reversed INTEGER DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS tx_period ON transactions(posted_date,account_id);
CREATE TABLE IF NOT EXISTS recurring_transactions(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),merchant TEXT,amount INTEGER,frequency TEXT,active INTEGER DEFAULT 1,evidence TEXT);
CREATE TABLE IF NOT EXISTS budgets(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),name TEXT,amount INTEGER);
CREATE TABLE IF NOT EXISTS budget_categories(budget_id TEXT REFERENCES budgets(id),category TEXT,amount INTEGER,PRIMARY KEY(budget_id,category));
CREATE TABLE IF NOT EXISTS financial_goals(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),name TEXT,target_amount INTEGER,current_amount INTEGER,target_date TEXT,priority INTEGER,status TEXT);
CREATE TABLE IF NOT EXISTS user_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id),emergency_fund_minimum INTEGER NOT NULL,preferred_currency TEXT,risk_preference TEXT,excluded_accounts TEXT DEFAULT '[]',rules TEXT NOT NULL,revision INTEGER DEFAULT 1);
CREATE TABLE IF NOT EXISTS memory_audit(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),previous_value TEXT,new_value TEXT,confirmed INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),title TEXT,document_type TEXT,version INTEGER,effective_date TEXT,superseded_by TEXT,checksum TEXT,ingestion_status TEXT,metadata TEXT,UNIQUE(user_id,checksum));
CREATE TABLE IF NOT EXISTS document_versions(id TEXT PRIMARY KEY,document_id TEXT REFERENCES documents(id),version INTEGER,checksum TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS document_chunks(id TEXT PRIMARY KEY,document_id TEXT REFERENCES documents(id),section TEXT,page INTEGER,content TEXT,embedding TEXT,provider TEXT,quarantined INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS scenario_runs(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS scenario_inputs(run_id TEXT PRIMARY KEY REFERENCES scenario_runs(id),payload TEXT);
CREATE TABLE IF NOT EXISTS scenario_results(run_id TEXT PRIMARY KEY REFERENCES scenario_runs(id),payload TEXT);
CREATE TABLE IF NOT EXISTS agent_runs(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),question TEXT,route TEXT,nodes TEXT,validation TEXT,latency_ms INTEGER,error TEXT,answer TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tool_calls(id TEXT PRIMARY KEY,run_id TEXT REFERENCES agent_runs(id),name TEXT,inputs TEXT,outputs TEXT,latency_ms INTEGER);
CREATE TABLE IF NOT EXISTS citations(id TEXT PRIMARY KEY,run_id TEXT REFERENCES agent_runs(id),document_id TEXT,chunk_id TEXT,passage TEXT);
CREATE TABLE IF NOT EXISTS evaluation_cases(test_id TEXT PRIMARY KEY,category TEXT,payload TEXT);
CREATE TABLE IF NOT EXISTS evaluation_runs(id TEXT PRIMARY KEY,metrics TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS evaluation_results(id TEXT PRIMARY KEY,run_id TEXT REFERENCES evaluation_runs(id),test_id TEXT,payload TEXT,passed INTEGER);
INSERT OR IGNORE INTO schema_migrations VALUES(1);
